using System.Security.Cryptography;
using System.Text;
using Meridian.Domain.Contractors;

namespace Meridian.Domain.Jobs;

/// <summary>
/// Contractor attendance (AD-6, AD-11, R20, R21). A sent job carries a single-job capability token: only its SHA-256
/// hash is stored on the job, and the raw token lives only in the outbound message and its link. Marking the job
/// attended, or resending it, invalidates the token it was sent with.
/// </summary>
public sealed partial class Job
{
    /// <summary>Random bytes in a contractor token before URL-safe base64 encoding.</summary>
    public const int ContractorTokenBytes = 32;

    /// <summary>Length of a stored token hash: SHA-256 as hex.</summary>
    public const int ContractorTokenHashLength = 64;

    /// <summary>The emergency promise (RULE-8): attended within this long of the first message.</summary>
    public static readonly TimeSpan EmergencyAttendanceWindow = TimeSpan.FromHours(24);

    /// <summary>SHA-256 of the contractor token, hex; null when no token is live (never sent, attended).</summary>
    public string? ContractorTokenHash { get; private set; }

    /// <summary>The contractor the job was last sent to; null until sent.</summary>
    public Guid? SentToContractorId { get; private set; }

    /// <summary>When the contractor marked the job attended (UTC); null until then.</summary>
    public DateTime? AttendedAtUtc { get; private set; }

    /// <summary>When the attendance-overdue alert was raised for the current send (UTC); null while not flagged.</summary>
    public DateTime? AttendanceOverdueFlaggedAtUtc { get; private set; }

    /// <summary>The stored form of a contractor token: SHA-256 of its UTF-8 bytes, as 64 hex characters.</summary>
    public static string HashContractorToken(string token)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            throw new ArgumentException("A contractor token is required.", nameof(token));
        }

        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token)));
    }

    /// <summary>True when <paramref name="token"/> is the live token of this job.</summary>
    public bool HasContractorToken(string token) =>
        !string.IsNullOrWhiteSpace(token)
        && ContractorTokenHash is { } hash
        && string.Equals(hash, HashContractorToken(token), StringComparison.Ordinal);

    /// <summary>
    /// Sends an Approved job to its contractor (AD-6: Approved → SentToContractor), in the same unit of work as the
    /// approval. Stores the token's hash and appends <see cref="EventType.SentToContractor"/> with the contractor and
    /// the outbound message the link was sent in.
    /// </summary>
    /// <param name="token">The raw token; only its hash is kept.</param>
    /// <param name="outboundId">The outbound message written for the contractor (AD-8).</param>
    /// <param name="actor">The person who approved or resent the job.</param>
    /// <exception cref="JobStateException">The job is not Approved.</exception>
    public void SendToContractor(Guid contractorId, string token, Guid outboundId, string actor, DateTime nowUtc)
    {
        RequirePersonActor(actor);
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (Status != JobStatus.Approved)
        {
            throw new JobStateException($"Job {Reference} is {Status} and cannot be sent to a contractor.", Status);
        }

        RequireSendArguments(contractorId, token, outboundId);
        Status = JobStatus.SentToContractor;
        Dispatch(contractorId, token, outboundId, actor, nowUtc);
    }

    /// <summary>
    /// Sends a job that is already SentToContractor to another contractor (the person's choice of fallback). The old
    /// token stops working, the new one is stored, the overdue flag is cleared, and <see cref="EventType.SentToContractor"/>
    /// is appended again. The status stays SentToContractor.
    /// </summary>
    /// <exception cref="JobStateException">The job is not SentToContractor.</exception>
    public void ResendToContractor(Guid contractorId, string token, Guid outboundId, string actor, DateTime nowUtc)
    {
        RequirePersonActor(actor);
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (Status != JobStatus.SentToContractor)
        {
            throw new JobStateException($"Job {Reference} is {Status} and cannot be re-sent to a contractor.", Status);
        }

        RequireSendArguments(contractorId, token, outboundId);
        AttendanceOverdueFlaggedAtUtc = null;
        Dispatch(contractorId, token, outboundId, actor, nowUtc);
    }

    /// <summary>
    /// The contractor marks the job attended through its link (AD-6: SentToContractor → Attended). The token is
    /// invalidated and <see cref="EventType.JobAttended"/> is appended with the actor <c>contractor:&lt;id&gt;</c>.
    /// </summary>
    /// <exception cref="JobStateException">The job is not SentToContractor.</exception>
    public void MarkAttended(DateTime nowUtc)
    {
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (Status != JobStatus.SentToContractor || SentToContractorId is not { } contractorId)
        {
            throw new JobStateException($"Job {Reference} is {Status} and cannot be marked attended.", Status);
        }

        var from = Status;
        Status = JobStatus.Attended;
        AttendedAtUtc = nowUtc;
        ContractorTokenHash = null;
        Append(
            EventType.JobAttended,
            nowUtc,
            ContractorActor(contractorId),
            new { from = from.ToString(), to = Status.ToString(), contractorId });
    }

    /// <summary>
    /// True when an Emergency job sent to a contractor is more than 24 hours past its first message and has not been
    /// flagged since it was last sent (RULE-8, AD-9).
    /// </summary>
    public bool IsAttendanceOverdue(DateTime nowUtc) =>
        Urgency == Urgency.Emergency
        && Status == JobStatus.SentToContractor
        && AttendanceOverdueFlaggedAtUtc is null
        && nowUtc - ReceivedAtUtc > EmergencyAttendanceWindow;

    /// <summary>
    /// Raises the attendance-overdue alert once (the worker's check, AD-9): appends <see cref="EventType.AttendanceOverdue"/>
    /// and sets the flag. Running it again changes nothing.
    /// </summary>
    /// <returns>True when the alert was raised now.</returns>
    public bool FlagAttendanceOverdue(DateTime nowUtc)
    {
        Guards.RequireUtc(nowUtc, nameof(nowUtc));
        if (!IsAttendanceOverdue(nowUtc))
        {
            return false;
        }

        AttendanceOverdueFlaggedAtUtc = nowUtc;
        Append(
            EventType.AttendanceOverdue,
            nowUtc,
            JobEvent.SystemActor,
            new { reference = Reference, contractorId = SentToContractorId, firstMessageAtUtc = ReceivedAtUtc });
        return true;
    }

    /// <summary>
    /// The rule behind the contractor the job is with: <see cref="SuggestedContractorRule"/> while the job was sent to the
    /// contractor first suggested for it, otherwise null (a fallback chosen by a person has no suggestion rule).
    /// </summary>
    public ContractorRule? SentContractorRule =>
        SentToContractorId is null || SentToContractorId == SuggestedContractorId ? SuggestedContractorRule : null;

    /// <summary>The actor written for a contractor's own action: <c>contractor:&lt;id&gt;</c>.</summary>
    public static string ContractorActor(Guid contractorId) => "contractor:" + contractorId.ToString("D");

    private static void RequireSendArguments(Guid contractorId, string token, Guid outboundId)
    {
        if (contractorId == Guid.Empty)
        {
            throw new ArgumentException("A contractor id is required.", nameof(contractorId));
        }

        if (outboundId == Guid.Empty)
        {
            throw new ArgumentException("An outbound message id is required.", nameof(outboundId));
        }

        HashContractorToken(token);
    }

    private void Dispatch(Guid contractorId, string token, Guid outboundId, string actor, DateTime nowUtc)
    {
        ContractorTokenHash = HashContractorToken(token);
        SentToContractorId = contractorId;
        Append(
            EventType.SentToContractor,
            nowUtc,
            actor,
            new { contractorId, outboundId });
    }
}
using Meridian.Application.Abstractions;

namespace Meridian.Application.Attendance;

/// <summary>
/// The overdue check, run by the escalation worker each tick (RULE-8, AD-9): every Emergency job sent to a contractor
/// that is more than 24 hours past its first message and not yet flagged gets <c>AttendanceOverdue</c> once and the
/// queue alert. Idempotent: a second run flags nothing.
/// </summary>
public sealed class CheckOverdueAttendance
{
    private readonly IJobRepository _jobs;
    private readonly IUnitOfWork _unitOfWork;
    private readonly IClock _clock;

    public CheckOverdueAttendance(IJobRepository jobs, IUnitOfWork unitOfWork, IClock clock)
    {
        _jobs = jobs;
        _unitOfWork = unitOfWork;
        _clock = clock;
    }

    /// <returns>The references of the jobs flagged by this run, in queue order; empty when none were due.</returns>
    public Task<IReadOnlyList<string>> ExecuteAsync(CancellationToken cancellationToken) =>
        _unitOfWork.ExecuteAsync<IReadOnlyList<string>>(async ct =>
        {
            var now = _clock.UtcNow;
            var flagged = new List<string>();
            foreach (var job in await _jobs.ListAwaitingAttendanceAsync(ct))
            {
                if (job.FlagAttendanceOverdue(now))
                {
                    flagged.Add(job.Reference);
                }
            }

            return flagged;
        }, cancellationToken);
}
using Meridian.Application.Outbox;
using Meridian.Application.Templates;
using Meridian.Domain.Contractors;
using Meridian.Domain.Jobs;
using Meridian.Domain.Outbox;

namespace Meridian.Application.Attendance;

/// <summary>
/// Sends a job to a contractor (AD-8, AD-11): a new token, the contractor message with its link written to the outbox,
/// and the job's <c>SentToContractor</c> change. Used by approval and by resend, inside their unit of work.
/// </summary>
internal static class ContractorDispatch
{
    /// <returns>The id of the outbound message written for the contractor.</returns>
    public static Guid Send(
        Job job,
        Contractor contractor,
        string? address,
        IOutbox outbox,
        string actor,
        DateTime nowUtc,
        bool resend)
    {
        var token = ContractorJobLink.NewToken();
        var body = ContractorTemplates.Render(
            job.Reference,
            address,
            job.Category.ToString(),
            job.SummaryEn,
            ContractorJobLink.PathFor(token));
        var outbound = outbox.Send(
            new OutboundRequest(job.Id, OutboundChannels.Sms, $"{contractor.Name} ({contractor.Phone})", ContractorTemplates.JobId, body),
            nowUtc);

        if (resend)
        {
            job.ResendToContractor(contractor.Id, token, outbound.Id, actor, nowUtc);
        }
        else
        {
            job.SendToContractor(contractor.Id, token, outbound.Id, actor, nowUtc);
        }

        return outbound.Id;
    }
}
using System.Security.Cryptography;
using Meridian.Domain.Jobs;

namespace Meridian.Application.Attendance;

/// <summary>
/// The single-job link a contractor opens (AD-11): <c>/c/&lt;token&gt;</c>, where the token is 32 random bytes as URL-safe
/// base64 without padding. Only the token's hash is stored on the job (<see cref="Job.HashContractorToken"/>).
/// </summary>
public static class ContractorJobLink
{
    public const string PathPrefix = "/c/";

    /// <summary>A new random token.</summary>
    public static string NewToken() =>
        Convert.ToBase64String(RandomNumberGenerator.GetBytes(Job.ContractorTokenBytes))
            .TrimEnd('=')
            .Replace('+', '-')
            .Replace('/', '_');

    /// <summary>The path of the link for a token.</summary>
    public static string PathFor(string token) => PathPrefix + token;
}
using Meridian.Application.Abstractions;
using Meridian.Domain.Jobs;

namespace Meridian.Application.Attendance;

/// <summary>What a contractor sees through its link: only that job's reference, address, category, summary and contractor name.</summary>
public sealed record ContractorJobView(string Reference, string? Address, string Category, string? Summary, string ContractorName);

/// <summary>
/// The contractor's view of one job (AD-11). A wrong, used or expired token gives null, which the API answers with 404
/// and no detail. Read-only.
/// </summary>
public sealed class GetContractorJob
{
    private readonly IJobRepository _jobs;
    private readonly IPropertyRepository _properties;
    private readonly IContractorRepository _contractors;

    public GetContractorJob(IJobRepository jobs, IPropertyRepository properties, IContractorRepository contractors)
    {
        _jobs = jobs;
        _properties = properties;
        _contractors = contractors;
    }

    public async Task<ContractorJobView?> ExecuteAsync(string token, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            return null;
        }

        var job = await _jobs.GetByContractorTokenHashAsync(Job.HashContractorToken(token), cancellationToken);
        if (job is null || job.Status != JobStatus.SentToContractor || !job.HasContractorToken(token) || job.SentToContractorId is not { } contractorId)
        {
            return null;
        }

        var property = job.PropertyId is { } propertyId
            ? (await _properties.ListAsync(cancellationToken)).FirstOrDefault(p => p.Id == propertyId)
            : null;
        var contractor = (await _contractors.ListAsync(cancellationToken)).FirstOrDefault(c => c.Id == contractorId);
        return new ContractorJobView(
            job.Reference,
            property?.Name,
            job.Category.ToString(),
            job.SummaryEn,
            contractor?.Name ?? string.Empty);
    }
}
using Meridian.Application.Abstractions;
using Meridian.Domain.Jobs;

namespace Meridian.Application.Attendance;

/// <summary>
/// The contractor marks the job attended through its link (R20, R21, AD-6): SentToContractor → Attended, the token is
/// invalidated, and the event is written in one unit of work. A wrong, used or expired token changes nothing.
/// </summary>
public sealed class MarkAttended
{
    private readonly IJobRepository _jobs;
    private readonly IUnitOfWork _unitOfWork;
    private readonly IClock _clock;

    public MarkAttended(IJobRepository jobs, IUnitOfWork unitOfWork, IClock clock)
    {
        _jobs = jobs;
        _unitOfWork = unitOfWork;
        _clock = clock;
    }

    /// <returns>The job reference when it was marked attended; null when the token matched no sent job.</returns>
    public async Task<string?> ExecuteAsync(string token, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(token))
        {
            return null;
        }

        return await _unitOfWork.ExecuteAsync<string?>(async ct =>
        {
            var job = await _jobs.GetByContractorTokenHashAsync(Job.HashContractorToken(token), ct);
            if (job is null || !job.HasContractorToken(token))
            {
                return null;
            }

            job.MarkAttended(_clock.UtcNow);
            return job.Reference;
        }, cancellationToken);
    }
}
using Meridian.Application.Abstractions;
using Meridian.Application.Outbox;
using Meridian.Application.Review;
using Meridian.Domain.Jobs;

namespace Meridian.Application.Attendance;

/// <summary>
/// A person sends a job that is already SentToContractor to another contractor (the fallback, after the overdue alert):
/// a new token and a new message, the old link stops working, the overdue flag is cleared and <c>SentToContractor</c>
/// is recorded again. Nothing is chosen automatically (AD-11). One unit of work; every check runs before anything changes.
/// </summary>
public sealed class ResendToContractor
{
    private readonly IJobRepository _jobs;
    private readonly IPropertyRepository _properties;
    private readonly IContractorRepository _contractors;
    private readonly IUnitOfWork _unitOfWork;
    private readonly IClock _clock;
    private readonly IOutbox _outbox;
    private readonly StaffDirectory _staff;

    public ResendToContractor(
        IJobRepository jobs,
        IPropertyRepository properties,
        IContractorRepository contractors,
        IUnitOfWork unitOfWork,
        IClock clock,
        IOutbox outbox,
        StaffDirectory staff)
    {
        _jobs = jobs;
        _properties = properties;
        _contractors = contractors;
        _unitOfWork = unitOfWork;
        _clock = clock;
        _outbox = outbox;
        _staff = staff;
    }

    public Task<ReviewResult> ExecuteAsync(Guid jobId, string? actor, Guid? contractorId, CancellationToken cancellationToken)
    {
        if (_staff.Find(actor) is not { } person)
        {
            return Task.FromResult(ReviewResult.Invalid(ReviewJob.Fields.Actor, "Choose who you are acting as."));
        }

        if (contractorId is not { } chosen || chosen == Guid.Empty)
        {
            return Task.FromResult(ReviewResult.Invalid(ReviewJob.Fields.ContractorId, "Choose a contractor to send the job to."));
        }

        return _unitOfWork.ExecuteAsync<ReviewResult>(async ct =>
        {
            var contractor = (await _contractors.ListAsync(ct)).FirstOrDefault(c => c.Id == chosen);
            if (contractor is null)
            {
                return ReviewResult.Invalid(ReviewJob.Fields.ContractorId, "Unknown contractor.");
            }

            var job = await _jobs.GetAsync(jobId, ct);
            if (job is null)
            {
                return ReviewResult.NotFound;
            }

            if (job.Status != JobStatus.SentToContractor)
            {
                return ReviewResult.Conflict($"Job {job.Reference} is {job.Status}; only a job sent to a contractor can be sent again.");
            }

            var address = job.PropertyId is { } propertyId
                ? (await _properties.ListAsync(ct)).FirstOrDefault(p => p.Id == propertyId)?.Name
                : null;
            ContractorDispatch.Send(job, contractor, address, _outbox, person.Id, _clock.UtcNow, resend: true);
            return ReviewResult.Done;
        }, cancellationToken);
    }
}
namespace Meridian.Application.Templates;

/// <summary>
/// The fixed text sent to a contractor when a job is approved or re-sent (AD-7, AD-11). Placeholders: the job
/// reference, the resolved address, the category, the English summary and the single-job link. The summary is model
/// output: it is shown to the contractor as job information only, never to a tenant (RULE-5 covers tenant text).
/// </summary>
public static class ContractorTemplates
{
    public const string ReferencePlaceholder = "{reference}";
    public const string AddressPlaceholder = "{address}";
    public const string CategoryPlaceholder = "{category}";
    public const string SummaryPlaceholder = "{summary}";
    public const string LinkPlaceholder = "{link}";

    /// <summary>The template id of a contractor job message.</summary>
    public const string JobId = "contractor-job";

    /// <summary>Shown for the summary when the job has none (no model outcome, e.g. a job a person created).</summary>
    public const string NoSummary = "no summary recorded";

    public const string Job =
        "Meridian job {reference}: {category} at {address}. Summary: {summary}. Please attend and, once the job is done, open {link} and press Mark attended.";

    /// <summary>Renders the contractor message.</summary>
    /// <param name="address">The property name, or null when unresolved.</param>
    /// <param name="summary">The English summary, or null when there is none.</param>
    /// <param name="link">The single-job link, e.g. <c>/c/&lt;token&gt;</c>.</param>
    public static string Render(string reference, string? address, string category, string? summary, string link)
    {
        if (string.IsNullOrWhiteSpace(reference))
        {
            throw new ArgumentException("A reference is required.", nameof(reference));
        }

        if (string.IsNullOrWhiteSpace(link))
        {
            throw new ArgumentException("A link is required.", nameof(link));
        }

        return Job
            .Replace(ReferencePlaceholder, reference, StringComparison.Ordinal)
            .Replace(AddressPlaceholder, string.IsNullOrWhiteSpace(address) ? StaffTemplates.UnresolvedAddress : address, StringComparison.Ordinal)
            .Replace(CategoryPlaceholder, category, StringComparison.Ordinal)
            .Replace(SummaryPlaceholder, string.IsNullOrWhiteSpace(summary) ? NoSummary : summary, StringComparison.Ordinal)
            .Replace(LinkPlaceholder, link, StringComparison.Ordinal);
    }
}

using Meridian.Application.Attendance;
using Meridian.Application.Abstractions;
using Meridian.Application.Review;
using Microsoft.AspNetCore.Mvc;

namespace Meridian.Web.Api;

/// <summary>
/// Contractor attendance (R20, R21, AD-11): the contractor's single-job view and "Mark attended" through the link
/// token, and a person sending an overdue job to a fallback contractor. A wrong, used or expired token is 404 with no
/// detail. The resend names its person in the <see cref="ReviewEndpoints.ActingAsHeader"/> header (no login).
/// </summary>
public static class AttendanceEndpoints
{
    public static RouteGroupBuilder MapAttendanceApi(this RouteGroupBuilder api)
    {
        api.MapGet("/contractor-jobs/{token}", async (string token, GetContractorJob getJob, CancellationToken ct) =>
            await getJob.ExecuteAsync(token, ct) is { } job
                ? Results.Ok(new ContractorJobDto(job.Reference, job.Address, job.Category, job.Summary, job.ContractorName))
                : ContractorJobNotFound());

        api.MapPost("/contractor-jobs/{token}/attended", async (string token, MarkAttended markAttended, CancellationToken ct) =>
            await markAttended.ExecuteAsync(token, ct) is { } reference
                ? Results.Ok(new ContractorAttendedDto(reference, "Attended"))
                : ContractorJobNotFound());

        api.MapPost("/jobs/{id:guid}/resend", async (
            Guid id,
            [FromHeader(Name = ReviewEndpoints.ActingAsHeader)] string? actingAs,
            ResendRequest? request,
            ResendToContractor resend,
            GetJob getJob,
            CancellationToken ct) =>
            await ReviewEndpoints.ToResultAsync(await resend.ExecuteAsync(id, actingAs, request?.ContractorId, ct), id, getJob, ct));

        return api;
    }

    private static IResult ContractorJobNotFound() =>
        Results.Problem(statusCode: StatusCodes.Status404NotFound, title: "Job not found");
}

/// <summary>What the contractor sees of its job: nothing about any other job, the tenant or the property's other details.</summary>
public sealed record ContractorJobDto(string Reference, string? Address, string Category, string? Summary, string ContractorName);

/// <summary>The result of "Mark attended".</summary>
public sealed record ContractorAttendedDto(string Reference, string Status);

/// <summary>The fallback contractor a person sends an overdue job to.</summary>
public sealed record ResendRequest(Guid? ContractorId);
