import { useEffect, useState } from 'react';
import { errorText, getContractorJob, markContractorJobAttended, type ContractorJob } from './api';

/** The token from a contractor link path such as "/c/abc123", or null when the path is not a contractor link. */
export function contractorTokenFromPath(pathname: string): string | null {
  if (!pathname.startsWith('/c/')) {
    return null;
  }
  const token = pathname.slice('/c/'.length).replace(/\/+$/, '');
  return token.length > 0 ? decodeURIComponent(token) : null;
}

const INVALID_LINK = 'This link is not valid. It may already have been used, or replaced by a newer one.';

/**
 * The contractor's page for one job (AD-11, R20): the job's reference, address, category, summary and the contractor's
 * name, and "Mark attended". It shows nothing about any other job and needs no sign-in.
 */
export function ContractorPage({ token }: { token: string }) {
  const [job, setJob] = useState<ContractorJob | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [attended, setAttended] = useState<string | null>(null);
  const [marking, setMarking] = useState(false);
  const [markError, setMarkError] = useState<string | null>(null);

  useEffect(() => {
    getContractorJob(token)
      .then(setJob)
      .catch(() => setLoadError(INVALID_LINK));
  }, [token]);

  async function onMarkAttended() {
    setMarking(true);
    setMarkError(null);
    try {
      const result = await markContractorJobAttended(token);
      setAttended(result.reference);
    } catch (e) {
      setMarkError(errorText(e) === 'Job not found' ? INVALID_LINK : errorText(e));
    } finally {
      setMarking(false);
    }
  }

  return (
    <main>
      <header className="page-header">
        <h1>Meridian job</h1>
      </header>

      {loadError && (
        <section className="panel" aria-live="polite">
          <p role="alert" className="error">
            {loadError}
          </p>
        </section>
      )}

      {job && (
        <section className="panel contractor-page" aria-labelledby="job-heading">
          <h2 id="job-heading">{job.reference}</h2>
          <dl className="facts">
            <dt>Address</dt>
            <dd>{job.address ?? 'Not resolved'}</dd>
            <dt>Work</dt>
            <dd>{job.category}</dd>
            <dt>Summary</dt>
            <dd>{job.summary ?? 'No summary recorded.'}</dd>
            <dt>Contractor</dt>
            <dd>{job.contractorName}</dd>
          </dl>

          {attended ? (
            <p role="status">Thank you. {attended} is marked attended.</p>
          ) : (
            <div className="actions">
              <button type="button" className="mark-attended" disabled={marking} onClick={() => void onMarkAttended()}>
                {marking ? 'Marking…' : 'Mark attended'}
              </button>
              {markError && (
                <span role="alert" className="error">
                  {markError}
                </span>
              )}
            </div>
          )}
        </section>
      )}
    </main>
  );
}
import { useEffect, useState } from 'react';
import { errorText, listContractors, resendJob, type ContractorOption, type JobListItem } from './api';

/** The fallback suggested for an overdue job: another contractor for its category, else any other contractor. */
function suggestedFallback(job: JobListItem, contractors: ContractorOption[]): string {
  const others = contractors.filter((c) => c.id !== job.suggestedContractorId);
  return (others.find((c) => c.trade === job.category) ?? others[0])?.id ?? '';
}

/**
 * The alert at the top of the queue for emergencies not attended within 24 hours of their first message (RULE-8).
 * A person picks a fallback contractor and re-sends; the old link stops working (R21). Nothing is chosen automatically.
 */
export function OverdueAlert({
  jobs,
  actingAs,
  actingAsName,
  onResent,
}: {
  jobs: JobListItem[];
  actingAs: string | null;
  actingAsName: string | null;
  onResent: () => void;
}) {
  const [contractors, setContractors] = useState<ContractorOption[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    if (jobs.length === 0) {
      return;
    }
    listContractors()
      .then((list) => {
        setContractors(list);
        setLoadError(null);
      })
      .catch((e: unknown) => setLoadError(errorText(e)));
  }, [jobs.length]);

  if (jobs.length === 0) {
    return null;
  }

  return (
    <section className="panel overdue-alert" aria-labelledby="overdue-heading">
      <h2 id="overdue-heading">Overdue: not attended within 24 hours</h2>
      {loadError && (
        <p role="alert" className="error">
          {loadError}
        </p>
      )}
      {jobs.map((job) => (
        <OverdueRow
          key={`${job.id}-${job.suggestedContractorId ?? ''}`}
          job={job}
          contractors={contractors}
          actingAs={actingAs}
          actingAsName={actingAsName}
          onResent={onResent}
        />
      ))}
    </section>
  );
}

function OverdueRow({
  job,
  contractors,
  actingAs,
  actingAsName,
  onResent,
}: {
  job: JobListItem;
  contractors: ContractorOption[];
  actingAs: string | null;
  actingAsName: string | null;
  onResent: () => void;
}) {
  const [chosen, setChosen] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const selected = chosen ?? suggestedFallback(job, contractors);
  const fallbacks = contractors.filter((c) => c.id !== job.suggestedContractorId);

  async function onSend() {
    if (!actingAs || !selected) {
      return;
    }
    setSending(true);
    setError(null);
    try {
      await resendJob(job.id, actingAs, selected);
      onResent();
    } catch (e) {
      setError(`${job.reference}: ${errorText(e)}`);
    } finally {
      setSending(false);
    }
  }

  return (
    <div className="overdue-row">
      <p>
        <strong>{job.reference}</strong> {job.propertyName ?? 'address unresolved'} · {job.category} · sent to{' '}
        {job.suggestedContractorName ?? 'a contractor'}. <span className="overdue-label">Overdue: send fallback</span>
      </p>
      <div className="actions">
        <label htmlFor={`fallback-${job.id}`}>Fallback contractor</label>
        <select
          id={`fallback-${job.id}`}
          value={selected}
          onChange={(e) => setChosen(e.target.value)}
          disabled={fallbacks.length === 0}
        >
          {fallbacks.map((c) => (
            <option key={c.id} value={c.id}>
              {c.name} ({c.trade}, {c.phone})
            </option>
          ))}
        </select>
        <button type="button" disabled={sending || !actingAs || !selected} onClick={() => void onSend()}>
          {sending ? 'Sending…' : `Send to fallback as ${actingAsName ?? '…'}`}
        </button>
        {error && (
          <span role="alert" className="error">
            {error}
          </span>
        )}
      </div>
    </div>
  );
}
